{"code": "import os, json
p='/home/toxic/fleet/jobs'
items=os.listdir(p)
failed=[]
for d in items:
    dp=os.path.join(p,d)
    st_file=os.path.join(dp,'status')
    if not os.path.exists(st_file): continue
    with open(st_file) as f: s=f.read().strip()
    if s=='failed':
        res_file=os.path.join(dp,'result.json')
        if os.path.exists(res_file):
            try:
                with open(res_file) as f: data=json.load(f)
                cmd=data.get('cmd',[])
                name=data.get('name','')
                failed.append((d,name,cmd[0] if cmd else '',data.get('exit_code','')))
            except Exception as e:
                failed.append((d,'bad_json',str(e),''))
print('Failed jobs:', len(failed))
for d,name,cmd,ec in failed[:10]:
    print(' ',d,'|',name,'|',cmd,'| exit=',ec)
# tally first words of cmd
from collections import Counter
c=Counter()
for _,_,cmd,_ in failed:
    c[cmd]+=1
print('\nCommand tally (first token):')
for k,v in c.most_common(): print(' ',k,v)
", "language": "py", "timeout": 15, "title": "step 2 failure tally"}

