import os, subprocess
# Search grabbed files for bridge references
d='/home/toxic/phone-grab'
for f in sorted(os.listdir(d)):
    fp=os.path.join(d,f)
    if not os.path.isfile(fp): continue
    try:
        txt=open(fp,'rb').read(50000).decode('utf-8','replace')
    except: continue
    for i,line in enumerate(txt.splitlines()):
        if 'bridge' in line.lower() or 'piwire' in line.lower() or 'kap' in line.lower():
            print(f'{f}:{i+1}: {line[:200]}')
